  'admin_user_company_00176' => 'Discounts apply to value-added packages purchased by different membership levels. 0 and 100 mean no discount; 88 means 12% off.',
  'admin_user_company_00177' => 'Package mode controls quantities such as resume downloads. Time mode is unlimited during the service period but can limit daily usage.',
  'admin_user_company_00178' => 'Time membership - the basic package limits daily operations, e.g. up to X resume downloads per day.',
  'admin_user_company_00179' => 'Company membership levels affect revenue. Add and edit them carefully and keep the overall structure reasonable.',
  'admin_user_company_00180' => 'Companies receive points when purchasing packages, usable for job pinning, urgent recruitment, and other services.',
  'admin_user_company_00181' => 'Regardless of whether the company is paused, it expires after the maximum validity period.',
  'admin_user_company_00182' => 'Total listed job quota, shared by package mode and time mode without distinction.',
  'admin_user_company_00183' => 'Maximum validity cannot be shorter than service time. 0 means unlimited.',
