  'common_00012' => '{{config.integral_pricename}} (1 CNY={{config.integral_proportion}}{{config.integral_pricename}})',
  'common_00013' => '{{config.integral_pricename}} (1 CNY={{config.integral_proportion + config.integral_pricename}})',
  'common_00014' => 'Summarize your strengths in one or two sentences and highlight what makes you stand out.\\nExample:\\n2 years of sales management experience. As a regional lead, helped the team achieve the top mobile business volume in the province. Strong communicator, quick thinker, skilled in management, organization, and marketing methods.',
