  'default_00157' => 'No download required, no phone storage used, low data usage, and no device restrictions. With a touchscreen phone, job opportunities are at your fingertips.',
  'default_00158' => 'Built with HTML5+CSS3 for faster speed, lower traffic, and a better user experience, helping you find jobs easily anytime, anywhere.',
  'default_00159' => 'Create a resume quickly and apply to all jobs. Save a bookmark so you can access it with one click.',
  'default_00160' => 'Search jobs anytime, apply easily, and keep your career future in hand.',
  'default_00161' => 'A new UI experience for easy job search',
  'default_00162' => 'Instant resume applications and thoughtful interview notifications,',
  'default_00163' => 'Explore job search stories over the years,',
  'default_00164' => 'Leading HTML5+CSS3 Technology',
  'default_00165' => 'helping you avoid missing any interview notice.',
  'default_00166' => 'Global Positioning System GPS',
  'default_00167' => 'Find Jobs . Recruit Talent with One Tap',
  'default_00168' => 'So many jobs are close to home',
  'default_00169' => 'Precise Search . Smart Matching',
  'default_00170' => 'All core desktop features',
  'default_00171' => 'helping you search for jobs easily.',
