  'default_00175' => 'Full Features',
  'default_00176' => 'One-click Apply',
  'default_00177' => 'Reply with a position, such as accountant, clerk, sales assistant, driver, etc., and the system will recommend the latest jobs to you.',
  'default_00178' => 'Interview notifications can be activated after checking in within 48 hours. Do not miss any interview opportunity.',
  'default_00179' => 'Send your location and the system will recommend nearby jobs. Good jobs can be close to home.',
  'default_00180' => 'Good preparation makes good jobs easier to get, and interviews become much easier.',
  'default_00181' => 'Matched by your location, with more than 20 suitable positions within 300 meters.',
  'default_00182' => 'Do not miss opportunities. Bind your account to receive interview notifications immediately.',
  'default_00183' => 'A professional team filters jobs every week to bring you the positions you want most.',
  'default_00184' => 'Update your resume anytime and anywhere, and do not stay as a fresh graduate forever.',
